import 'package:flutter/material.dart';class ResultScreen extends StatelessWidget {  const ResultScreen({super.key});  @override  Widget build(BuildContext context) {    return Scaffold(        body: SafeArea(      child: Padding(          padding: const EdgeInsetsDirectional.symmetric(              horizontal: 35, vertical: 70),          child: Stack(            clipBehavior: Clip.none,            children: [              _shapeContainer(),              _bookMark(),              _line(context),              _cutFromLeft(context),              _cutFromRight(context),            ],          )),    ));  }  Positioned _cutFromLeft(BuildContext context) {    return Positioned(                left: -15,                bottom: MediaQuery.of(context).size.height * .2,                child: const CircleAvatar(                  backgroundColor: Colors.white,                ));  }  Positioned _cutFromRight(BuildContext context) => Positioned(                  right: -15,                  bottom: MediaQuery.of(context).size.height * .2,                  child: const CircleAvatar(                    backgroundColor: Colors.white,                  ));  Positioned _line(BuildContext context) => Positioned(                bottom: MediaQuery.of(context).size.height * .22,                left: 0,                right: 0,                child: Row(                  mainAxisAlignment: MainAxisAlignment.center,                  children: List.generate(30, (index) {                    return Container(                      width: 5,                      height: 2,                      margin: const EdgeInsets.symmetric(horizontal: 2),                      color: Colors.grey,                    );                  }),                ),              );  Container _shapeContainer() {    return Container(              decoration: ShapeDecoration(                  color: const Color(0xFFD9D9D9),                  shape: RoundedRectangleBorder(                    borderRadius: BorderRadius.circular(20),                  )),            );  }  Positioned _bookMark() {    return const Positioned(              top: -50,              right: 0,              left: 0,              child: Align(                  child: CircleAvatar(                radius: 50,                backgroundColor: Color(0xFFD9D9D9),                child: CircleAvatar(                  backgroundColor: Color(0xff34A853),                  radius: 40,                  child: Icon(                    Icons.check,                    size: 60,                    color: Colors.white,                  ),                ),              )),            );  }}